@* Toolbar with sort dropdown and result count label *@

<div class="d-flex justify-content-between align-items-center mb-3">
    <div>
        <label class="form-label mb-0 me-2 fw-semibold" for="sortSelect">Sort by:</label>
        <select id="sortSelect" class="form-select form-select-sm d-inline-block w-auto"
                value="@SortBy" @onchange="HandleSortChanged">
            <option value="price_asc">Price: Low to High</option>
